7	export class Helpers {
8	  static deg(v: number): number {
9	    return v;
10	  }
11	
12	  static degToRad(v: number): number {
13	    return (v * Math.PI) / 180;
14	  }
15	
16	  static rotationDegToRad(rot: { x: number; y: number; z: number }): {
17	    x: number;
18	    y: number;
19	    z: number;
20	  } {
21	    return {
22	      x: Helpers.degToRad(rot.x),
23	      y: Helpers.degToRad(rot.y),
24	      z: Helpers.degToRad(rot.z),
25	    };
26	  }
27	
28	  static rotationDegToRadPartial(
29	    rot: Vector3Optional | undefined,
30	  ): Record<string, number> {
31	    const out: Record<string, number> = {};
32	    if (rot?.x != null) out.x = Helpers.degToRad(rot.x);
33	    if (rot?.y != null) out.y = Helpers.degToRad(rot.y);
34	    if (rot?.z != null) out.z = Helpers.degToRad(rot.z);
35	    return out;
36	  }
37	
38	  static radToDeg(v: number): number {
39	    return (v * 180) / Math.PI;
40	  }
41	
42	  static applyRotationDeg(
43	    target: THREE.Object3D,
44	    rotation: Vector3Optional | undefined,
45	  ): void {
46	    const resolved = Helpers.rotationDegToRad({
47	      x: rotation?.x ?? 0,
48	      y: rotation?.y ?? 0,
49	      z: rotation?.z ?? 0,
50	    });
51	    Helpers.assignVec3(target.rotation, resolved);
52	  }
53	
54	  static applyTransform(
55	    target: THREE.Object3D,
56	    transform: TransformObjectOptions | undefined,
57	  ): void {
58	    target.position.set(
59	      transform?.position?.x ?? 0,
60	      transform?.position?.y ?? 0,
61	      transform?.position?.z ?? 0,
62	    );
63	    Helpers.applyRotationDeg(target, transform?.rotation);
64	    target.scale.set(
65	      transform?.scale?.x ?? 1,
66	      transform?.scale?.y ?? 1,
67	      transform?.scale?.z ?? 1,
68	    );
69	  }
70	
71	  static readRotationDeg(
72	    target: THREE.Object3D | null | undefined,
73	  ): { x: number; y: number; z: number } {
74	    return {
75	      x: Helpers.radToDeg(target?.rotation.x ?? 0),
76	      y: Helpers.radToDeg(target?.rotation.y ?? 0),
77	      z: Helpers.radToDeg(target?.rotation.z ?? 0),
78	    };
79	  }
80	
81	  static clamp(value: number, min: number, max: number): number {
82	    return Math.min(Math.max(value, min), max);
83	  }
84	
85	  static clamp01(value: number): number {
86	    if (!Number.isFinite(value)) return 0;
87	    return Helpers.clamp(value, 0, 1);
88	  }
89	
90	  static lerp(a: number, b: number, t: number): number {
91	    return a + (b - a) * t;
92	  }
93	
94	  static lerpClamped(a: number, b: number, t: number): number {
95	    return Helpers.lerp(a, b, Helpers.clamp01(t));
96	  }
97	
98	  static remap01(value: number, start: number, end: number): number {
99	    if (!Number.isFinite(value)) return 0;
100	    const range = end - start;
101	    if (range <= 0) return value >= end ? 1 : 0;
102	    return Helpers.clamp01((value - start) / range);
103	  }
104	
105	  static assignVec3(
106	    target: { x: number; y: number; z: number },
107	    vars: { x?: number; y?: number; z?: number },
108	  ): void {
109	    if (vars.x != null) target.x = vars.x;
110	    if (vars.y != null) target.y = vars.y;
111	    if (vars.z != null) target.z = vars.z;
112	  }
113	
114	  static assignRotationDeg(
115	    target: { x: number; y: number; z: number },
116	    vars: Vector3Optional | undefined,
117	  ): void {
118	    Helpers.assignVec3(target, Helpers.rotationDegToRadPartial(vars));
119	  }
120	
121	  static hexToVec3(hex: string): number[] {
122	    const num = parseInt(hex.slice(1), 16);
123	    return [
124	      ((num / 65536) % 256) / 255,
125	      ((num / 256) % 256) / 255,
126	      (num % 256) / 255,
127	    ];
128	  }
129	
130	  static hexToRgba(hex: string, alpha = 1): string {
131	    const r = parseInt(hex.slice(1, 3), 16);
132	    const g = parseInt(hex.slice(3, 5), 16);
133	    const b = parseInt(hex.slice(5, 7), 16);
134	    return `rgba(${r},${g},${b},${alpha})`;
135	  }
136	
137	  static lightenHex(hex: string, amount: number): string {
138	    return [
139	      "#",
140	      ...[1, 3, 5].map((index) =>
141	        Math.min(255, parseInt(hex.slice(index, index + 2), 16) + amount)
142	          .toString(16)
143	          .padStart(2, "0"),
144	      ),
145	    ].join("");
146	  }
147	
148	  
149	  static blendHexColors(hexA: string, hexB: string, t: number): number[] {
150	    const a = Helpers.hexToVec3(hexA);
151	    const b = Helpers.hexToVec3(hexB);
152	    return [
153	      a[0] + (b[0] - a[0]) * t,
154	      a[1] + (b[1] - a[1]) * t,
155	      a[2] + (b[2] - a[2]) * t,
156	    ];
157	  }
158	
159	  static sanitizeImmediateVars(
160	    vars: Record<string, unknown>,
161	  ): Record<string, unknown> {
162	    const out: Record<string, unknown> = {};
163	    for (const [key, value] of Object.entries(vars)) {
164	      if (key === "duration" || key === "ease" || key === "delay") continue;
165	      out[key] = value;
166	    }
167	    return out;
168	  }
169	
170	  static normalizeControlVars(
171	    vars: Record<string, unknown>,
172	  ): Record<string, unknown> {
173	    const next = { ...vars };
174	    const hasVisible = typeof next.visible === "boolean";
175	    const hasShow = typeof next.show === "boolean";
176	    const hasHide = typeof next.hide === "boolean";
177	
178	    if (!hasVisible && hasShow) next.visible = next.show;
179	    if (!hasVisible && !hasShow && hasHide) next.visible = !(next.hide as boolean);
180	
181	    delete next.show;
182	    delete next.hide;
183	    return next;
184	  }
185	
186	  static debounce<T extends (...args: unknown[]) => void>(
187	    fn: T,
188	    ms: number,
189	  ): (...args: Parameters<T>) => void {
190	    let id: ReturnType<typeof setTimeout> | null = null;
191	    return (...args: Parameters<T>) => {
192	      if (id != null) clearTimeout(id);
193	      id = setTimeout(() => {
194	        fn(...args);
195	        id = null;
196	      }, ms);
197	    };
198	  }
199	
200	  
201	  static throttle<T extends (...args: unknown[]) => void>(
202	    fn: T,
203	    ms: number,
204	  ): (...args: Parameters<T>) => void {
205	    let last = 0;
206	    return (...args: Parameters<T>) => {
207	      const now = Date.now();
208	      if (now - last < ms) return;
209	      last = now;
210	      fn(...args);
211	    };
212	  }
