**File:** `/resource/ts/utils/Helpers.ts` (lines 54-69)

The `applyTransform()` utility converts degrees to radians and applies the rotation:

```typescript
static applyTransform(
  target: THREE.Object3D,
  transform: TransformObjectOptions | undefined,
): void {
  target.position.set(
    transform?.position?.x ?? 0,
    transform?.position?.y ?? 0,
    transform?.position?.z ?? 0,
  );
  Helpers.applyRotationDeg(target, transform?.rotation);
  target.scale.set(
    transform?.scale?.x ?? 1,
    transform?.scale?.y ?? 1,
    transform?.scale?.z ?? 1,
